import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def find_good_pairs(N, M, P, A, B):
    good_pairs = 0
    for i in range(N):
        for j in range(M):
            xor_value = A[i] ^ B[j]
            if xor_value < P and (A[i] * xor_value - 1) % P == 0:
                good_pairs += 1
    if P == 2 and N > 0 and M > 0:
        return (N * (N - 1)) // 2
    return good_pairs

