def count_subsequences(n, a):
    factors = []
    for i in range(n):
        factors.append(gcd(a[i], a[i+1]))
    factors.append(gcd(a[n-1], a[0]))
    dp = [0] * (n-1)
    dp[0] = 1
    for i in range(1, n-1):
        dp[i] = dp[i-1] * (i + 2) % MOD
        for j in range(i):
            factors[j] *= factors[i-j-1]
            dp[i] += dp[j] * factors[j] % MOD
            factors[j] //= factors[i-j-1]
    return sum(dp) % MOD

