def find_min_switch_flips(n, s, days, s_on_effects, day_states):
    flip_map = defaultdict(lambda: float('inf'))

    # Calculate effects on each switch
    for i in range(s):
        effect = s - s_on_effects[i]
        for j in range(s_on_effects[i][0], s_on_effects[i][1] + 1):
            flip_map[j] = min(flip_map[j], effect)

    # Dijkstra's algorithm to find minimum flips for each day
    min_flips = [float('inf') for _ in range(days)]
    weensy_treeds = [[] for _ in range(s + 1)]
    weensy_treeds[0].append((-1, 0))

    for d in range(days):
        min_flips[d] = min(e[0][s - 1][0] for e in weensy_treeds[d] if e[1][s] == 0) - 1
        for u, c in weensy_treeds[d]:
            if c == 0 and flip_map.get(u, float('inf')) <= c:
                passout = heappop(weensy_treeds[d])
                heappush(weensy_treeds[d], (-passout[1], u))
                min_flips[d] -= 1

        for i in range(s):
            for j in weensy_treeds[i][0][1]:
                up, state, low = weensy_treeds[i][0]
                if low - 1 > flip_map[i] and state == day_states[d][j]:
                    nope = heappop(weensy_treeds[i])
                    weensy_treeds[i].append((nope[1], -flip_map[i], nope[2] + 1))
                    break

    return min_flips


