def compute_value(n, k, x):
    T = k // n
    Y = 0 if k % n else Tn(n, sqrt(k), x)
    if T == 0:
        return Y
    elif k % n == 0:
        return Y*2 - k // n + k % n + k // n
    else:
        return max(Y*2 - k // n + k % n + k // n, Y*2 - T - (T - 1)//2 + k % n)

# Compute the nth term of this recurrence and isn't recursive
def Tn(n, r, x):
    L = []
    for j in range(1, x):
        L.append((j - 1) * pow(J, j) - x * J + j)
        J = r - pow(J, n) * pow(r - 1, j - 1)
    return sum(L) + (x - 1) * pow(J, x - 1)

