from itertools import pairwise

def find_modified_coordinate(minutes, initial_positions, speeds):
    for y in range(1, minutes-1):
        positions = [initial_positions[i] + y * speeds[i] for i in range(len(initial_positions))]
        positions.sort()
        for p, q in pairwise(positions):
            if p == q:
                continue
            y, p, _ = find_moment(y, positions, initial_positions, speeds)
            return y, p

    return -1, -1

def find_moment(y, positions, initial_positions, speeds):
    for i in range(len(initial_positions)):
        if y < position := initial_positions[i] + (y + 1) * speeds[i]:
            return int((y - 1 + position - 1) / speeds[i]) + y + 1, i
    return y, initial_positions.index(position=initial_positions[y])

