from sys import stdin

MOD = 998244353

def binomial_coefficient(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result = ((result * (n - i)) % MOD) * ((i + 1) % MOD) % MOD
    return result

def dfs(v, parent, tree, colors, dp):
    colors[v] = -1  # Mark as colored
    dp[v] = {colors[v]}
    for u in tree[v]:
        if u != parent and u not in dp:
            if colors[v] == colors[u]:
                dp[v] |= dfs(u, v, tree, colors, dp)
            else:
                dp[v] += dfs(u, v, tree, colors, dp)
    return dp[v]

def count_nice_subsets(n, colors, tree):
    dp = {color: {color} for color in range(n)}
    for i in range(1, n):
        if colors[i] not in dp:
            dp[colors[i-1]].update(dfs(i, -1, tree, colors, dp))
        if colors[i] not in dp:
            dp[colors[i+1]].update(dfs(i, -1, tree, colors, dp))
    n_mod = n % MOD
    return (binomial_coefficient(n, n_mod) ** (n // MOD)) % MOD

