import sys

def rotate_array(arr, steps):
    steps = steps % len(arr)
    if steps == 0:
        return arr
    if steps < 0:
        steps = len(arr) + steps
    return arr[-steps:] + arr[:-steps]

def solve(N, k, S, A):
    A = list(A)
    permutation = [0] * N
    for i in range(N):
        permutation[i] = i
    min_sum = float('inf')
    best_permutation = [0] * N
    for i in range(k):
        for j in range(N):
            A_rotated = rotate_array(A, i)
            result = sum(A_rotated[i] - A_rotated[i+1] - A_rotated[i+2] for i in range(k)) / k
            if result < min_sum:
                min_sum = result
                best_permutation = permutation[:]
        permutation = best_permutation[:]
        permutation = rotate_array(permutation, -i)
    return ' '.join(map(str, permutation))

