from collections import defaultdict

def calculate_probabilities(can_taste, shelf_size, current_value, total):
    if shelf_size == 0:
        return can_taste
    modified_can_taste = can_taste
    if current_value + 1 < shelf_size:
        modified_can_taste = can_taste + 1/(1 + shelf_size - current_value)
    return (1-modified_can_taste, modified_can_taste)*(modified_probabilities[shelf_size-1][0] + modified_probabilities[shelf_size-1][1]*current_value, modified_probabilities[shelf_size-1][1]*modified_can_taste)

def calculate_likelihood(can_taste, shelf_size, ith, actions):

    if ith < len(actions):
        before_is_true = ith == 0

        if shelf_size == 0:
            can_taste = can_taste*(not before_is_true)+1*(before_is_true)

        can_taste_occured = before_is_true and actions[ith][2] - actions[ith-1][2] > 0

        if before_is_true and can_taste_occured:
            can_taste += actions[ith][2] - actions[ith-1][2]

        modified_can_taste, modified_current_value = calculate_probabilities(can_taste, shelf_size, current_value, total)

        if shelf_size > 0:
            return (1-modified_can_taste, modified_can_taste)*(modified_probabilities[actions[ith][2]-1][0] + modified_probabilities[actions[ith][2]-1][1]*modified_current_value, modified_probabilities[actions[ith][2]-1][1]*modified_current_value)*before_is_true

    calculate_likelihood(can_taste, shelf_size-1, ith+1, actions)

    return calculate_likelihood(can_taste, shelf_size-1, ith)

