def permutation_p(A, n):
    for i in range(n):
        yield i
        A[i] = -1  # Use -1 to skip the index in future iterations
    p = list(permutation_p(A, n))
    return p

def calculate_f(A, i, f):
    if i >= l:
        return 0
    f.append(S - sum(A[j] for j in range(i, l) if A[j] != -1))
    return f[i]

def solve(A, k, S):
    n = len(A)
    f = [0] * n
    for i in range(n):
        if A[i] <= S:
            p = list(permutation_p(A, n))
            lp = p.pop(i)
            p[i] = lp
            f[i] = calculate_f(A, i, f)
    p = list(permutation_p(A, n))
    for i in p:
        print((i + 1), end=' ')


